const item = $input.first().json;

let prd =
  item.candidates?.[0]?.content?.parts?.[0]?.text ??
  item.content?.parts?.[0]?.text ??
  item.text ??
  '';

prd = String(prd).replace(/^```(markdown|json)?|```$/gm, '').trim();

// If the model wrapped the PRD in JSON like {"markdown": "..."}, unwrap it
if (prd.startsWith('{')) {
  try {
    const obj = JSON.parse(prd);
    prd = obj.markdown || obj.prd || obj.content || prd;
  } catch (e) {}
}prd = prd.replace(/\\n/g, '\n');

return [{
  json: {
    prd_markdown: prd,
    extraction: $('Parse Extraction').first().json.extraction
  }
}];

values.content:
=You are a Story Breakdown agent. Convert the approved requirements into Epics, Features, and User Stories using ONLY the extraction JSON and PRD below.

Rules:
1. Every story must trace to at least one requirement ID in source_req_ids. Do not create stories for anything not in the source.
2. Use the format: "As a [persona], I want [capability], so that [benefit]". If the source states no benefit, omit the "so that" clause. Never invent a benefit.
3. If the source names multiple personas (for example Admin, End User, Auditor), create separate stories for each persona. Never merge them into a generic "user" story.
4. acceptance_criteria: copy ONLY items from the extraction's acceptance_criteria, verbatim. If none exist for a story, return an empty list. Never write new criteria.
5. NFR requirements (type "nfr") are listed by ID in linked_nfrs on the relevant stories. Do not rewrite or round their numbers.
6. Priority must be one of: "Must Have", "Should Have", "Nice to Have". Use "Must Have" for stated functional requirements unless the source uses an explicit priority word such as "nice to have", "optional", "if time permits", or "lower priority". Phrasing like "should be able to" is not a priority signal. Explain the choice in priority_rationale.
7. Do not resolve contradictions or ambiguities. If a story depends on an open question, list it in open_questions on that story, using only items from the extraction.
8. Return ONLY valid JSON. No prose, no code fences.

Schema:
{
  "epics": [
    {
      "id": "E1",
      "title": "",
      "description": "",
      "features": [
        {
          "id": "F1",
          "title": "",
          "stories": [
            {
              "id": "US1",
              "persona": "",
              "story": "",
              "acceptance_criteria": [],
              "linked_nfrs": [],
              "priority": "Must Have | Should Have | Nice to Have",
              "priority_rationale": "",
              "source_req_ids": [],
              "open_questions": []
            }
          ]
        }
      ]
    }
  ]
}

Extraction JSON:
{{ JSON.stringify($('Collect PRD').item.json.extraction, null, 2) }}

PRD:
{{ $('Collect PRD').item.json.prd_markdown }}

