const item = $input.first().json;

let raw =
  item.candidates?.[0]?.content?.parts?.[0]?.text ??
  item.content?.parts?.[0]?.text ??
  item.text ??
  item.output ??
  '';

raw = String(raw).replace(/```json|```/g, '').trim();

const repair = (s) => s
  .replace(/[\u201C\u201D]/g, '"')
  .replace(/([{,]\s*)([A-Za-z_][A-Za-z0-9_]*)"\s*:/g, '$1"$2":')
  .replace(/,\s*([}\]])/g, '$1');

let extraction;
let repaired = false;
try {
  extraction = JSON.parse(raw);
} catch (e1) {
  try {
    extraction = JSON.parse(repair(raw));
    repaired = true;
  } catch (e2) {
    extraction = {
      sufficiency: 'insufficient',
      stated_requirements: [],
      acceptance_criteria: [],
      stakeholders: [],
      personas: [],
      deadlines: [],
      dependencies: [],
      ambiguities: [],
      contradictions: [],
      missing_info: ['SYSTEM ERROR: the extractor output could not be parsed as JSON. Re-run the input.'],
      assumptions: [],
      parse_failed: true
    };
  }
}

if (!(extraction.stated_requirements || []).length) {
  extraction.sufficiency = 'insufficient';
}

return [{
  json: {
    extraction,
    sufficiency: String(extraction.sufficiency || '').trim().toLowerCase(),
    parse_failed: !!extraction.parse_failed,
    json_repaired: repaired,
    input_text: $('Input Guard').first().json.input_text
  }
}];

const item = $input.first().json;

let raw =
  item.candidates?.[0]?.content?.parts?.[0]?.text ??
  item.content?.parts?.[0]?.text ??
  item.text ??
  '';

raw = String(raw).replace(/```json|```/g, '').trim();

let gaps;
try {
  gaps = JSON.parse(raw);
} catch (e) {
  return [{ json: { parse_error: true, error: e.message, raw } }];
}

const ext = $('Parse Extraction').first().json.extraction;

let md = '# No PRD generated\n\nThe input does not contain enough information to extract requirements.\n';

md += '\n## What is missing\n';
(ext.missing_info || []).forEach(m => { md += `- ${m}\n`; });

if ((ext.ambiguities || []).length) {
  md += '\n## Ambiguous statements\n';
  ext.ambiguities.forEach(a => { md += `- ${a.item}: ${a.why_ambiguous}\n`; });
}
if ((ext.stakeholders || []).length) {
  md += '\n## Stakeholder viewpoints\n';
  ext.stakeholders.forEach(s => { md += `- ${s.name}${s.role ? ' (' + s.role + ')' : ''}: ${s.viewpoint}\n`; });
}
if ((ext.contradictions || []).length) {
  md += '\n## Tensions needing stakeholder resolution\n';
  ext.contradictions.forEach(c => { md += `- "${c.statement_a}" vs "${c.statement_b}"\n`; });
}
md += `\n## Clarification questions\nReadiness: ${gaps.readiness || 'Not ready'}\n`;
(gaps.questions || []).forEach(q => {
  md += `\n${q.id}. ${q.question}\n   - Ask: ${q.ask}\n   - Grounded in: ${q.grounded_in}\n`;
});

return [{
  json: {
    status: 'INSUFFICIENT',
    markdown: md,
    extraction: ext,
    gaps
  }
}];

const base = $('Parse Stories').first().json;
const stories = base.stories;
const prd = base.prd_markdown;
const gaps = $('Parse Gaps').first().json.gaps || {};
const est = $('Parse Estimates').first().json.estimates || {};

const byId = {};
(est.estimates || []).forEach(e => { byId[e.story_id] = e; });

let md = prd + '\n\n---\n\n# Epics, Features and User Stories\n';

(stories.epics || []).forEach(ep => {
  md += `\n## ${ep.id}: ${ep.title}\n${ep.description || ''}\n`;
  (ep.features || []).forEach(f => {
    md += `\n### ${f.id}: ${f.title}\n`;
    (f.stories || []).forEach(s => {
      const e = byId[s.id];
      md += `\n**${s.id}**: ${s.story}\n`;
      md += `- Priority: ${s.priority} (${s.priority_rationale})\n`;
      md += `- Source requirements: ${(s.source_req_ids || []).join(', ')}\n`;
      md += `- Linked NFRs: ${(s.linked_nfrs || []).join(', ') || 'None'}\n`;
      md += `- Acceptance criteria: ${(s.acceptance_criteria || []).length ? s.acceptance_criteria.join('; ') : 'None stated in source'}\n`;
      if (e) {
        md += `- Size (provisional): ${e.size}. ${e.rationale}\n`;
        if (e.underspecified) md += `- FLAG, underspecified: ${e.underspecified_reason}\n`;
      }
    });
  });
});

md += `\n---\n\n# Gap Analysis\nReadiness: ${gaps.readiness || 'Unknown'}\n`;
(gaps.questions || []).forEach(q => {
  md += `\n${q.id}. ${q.question}\n`;
  md += `   - Ask: ${q.ask}\n   - Blocking: ${q.blocking ? 'Yes' : 'No'}\n   - Grounded in: ${q.grounded_in}\n`;
});

return [{
  json: {
    status: 'COMPLETE',
    markdown: md,
    stories,
    gaps,
    estimates: est
  }
}];

// Edit these to match YOUR node names exactly
const MODEL = 'gemini-3.5-flash-lite';
const AGENTS = [
  { node: 'Requirement Extractor Agent', name: 'requirement_extractor' },
  { node: 'PRD Generator Agent', name: 'prd_generator' },
  { node: 'Story Breakdown Agent', name: 'story_breakdown' },
  { node: 'Gap Analyzer Agent', name: 'gap_analyzer' },
  { node: 'Scope Estimator Agent', name: 'scope_estimator' },
  { node: 'Gap Analyzer (Insufficient)', name: 'gap_analyzer_insufficient' }
];

const tryGet = (name) => {
  try { const i = $(name).first(); return i ? i.json : null; } catch (e) { return null; }
};
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0;
  return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});
const trunc = (v, n = 8000) => {
  const s = typeof v === 'string' ? v : JSON.stringify(v);
  return s && s.length > n ? s.slice(0, n) + '...[truncated]' : s;
};
const norm = s => String(s || '').replace(/\s+/g, ' ').trim().toLowerCase();

const now = new Date().toISOString();
const traceId = uuid();

// Which path did this run take?
let status = 'BLOCKED_BY_GUARD';
let finalOutput = tryGet('Insufficient Input');
if (tryGet('Format Output')) { status = 'COMPLETE'; finalOutput = tryGet('Format Output'); }
else if (tryGet('Format Insufficient Output')) { status = 'INSUFFICIENT'; finalOutput = tryGet('Format Insufficient Output'); }

const form = tryGet('On form submission') || {};
const guard = tryGet('Input Guard') || {};
const inputText = guard.input_text || form.input_text || '';
const parsed = tryGet('Parse Extraction');
const ext = parsed ? parsed.extraction : null;

const batch = [];
batch.push({
  id: uuid(), type: 'trace-create', timestamp: now,
  body: {
    id: traceId, name: 'prd-genie-run', timestamp: now,
    input: trunc(inputText),
    output: trunc(finalOutput && (finalOutput.markdown || finalOutput.message || finalOutput)),
       metadata: { status, input_type: form.input_type || null, sufficiency: ext ? ext.sufficiency : null, rag_chunks: (tryGet('Join Template') || {}).chunk_count ?? null },
    tags: ['prd-genie']
  }
});

// One generation per agent that actually ran
AGENTS.forEach(a => {
  const raw = tryGet(a.node);
  if (!raw) return;
  const text = raw.candidates?.[0]?.content?.parts?.[0]?.text ?? raw.content?.parts?.[0]?.text ?? raw.text ?? '';
  const um = raw.usageMetadata;
  const body = {
    id: uuid(), traceId, name: a.name, model: MODEL,
    startTime: now, endTime: now,
    input: a.name.startsWith('requirement') ? trunc(inputText) : `(stage input: output of previous agent; see n8n execution)`,
    output: trunc(text),
    metadata: { n8n_node: a.node }
  };
  if (um) {
    body.usageDetails = { input: um.promptTokenCount, output: um.candidatesTokenCount, total: um.totalTokenCount };
  } else {
    body.usageDetails = { output: Math.ceil(String(text).length / 4) };
    body.metadata.tokens_estimated = true;
  }
  batch.push({ id: uuid(), type: 'generation-create', timestamp: now, body });
});

// Score 1: quote grounding (deterministic hallucination check)
if (ext) {
  const src = norm(inputText);
  const reqs = ext.stated_requirements || [];
  const supported = reqs.filter(r => r.source_quote && src.includes(norm(r.source_quote))).length;
  const grounding = reqs.length ? supported / reqs.length : 1;
  batch.push({
    id: uuid(), type: 'score-create', timestamp: now,
    body: {
      id: uuid(), traceId, name: 'quote_grounding', value: grounding,
      comment: `${supported}/${reqs.length} extracted requirements have a source_quote found in the input`
    }
  });
}

// Score 2: story traceability
const st = tryGet('Parse Stories');
if (st && st.stories) {
  const all = [];
  (st.stories.epics || []).forEach(e => (e.features || []).forEach(f => (f.stories || []).forEach(s => all.push(s))));
  const traced = all.filter(s => (s.source_req_ids || []).length > 0).length;
  batch.push({
    id: uuid(), type: 'score-create', timestamp: now,
    body: {
      id: uuid(), traceId, name: 'story_traceability', value: all.length ? traced / all.length : 1,
      comment: `${traced}/${all.length} stories cite a source requirement`
    }
  });
}

const sp = tryGet('Parse Stories');
const result = {
  test_id: guard.test_id || null,
  source_file: guard.source_file || null,
  trace_id: traceId,
  input_text: inputText,
  status,
  markdown: finalOutput ? (finalOutput.markdown || finalOutput.message || '') : '',
  prd_markdown: (tryGet('Collect PRD') || {}).prd_markdown || '',
  extraction: ext,
  stories: sp ? sp.stories : null,
  gaps: (tryGet('Parse Gaps') || {}).gaps || (finalOutput && finalOutput.gaps) || null,
  estimates: (tryGet('Parse Estimates') || {}).estimates || null,
  parse_failed: parsed ? !!parsed.parse_failed : false,
  json_repaired: parsed ? !!parsed.json_repaired : false
};

return [{ json: { trace_id: traceId, status, body: { batch }, result } }];

const chunks = $input.all()
  .map(i => i.json.document?.pageContent ?? i.json.pageContent ?? i.json.text ?? '')
  .filter(Boolean);

return [{
  json: {
    template_context: chunks.join('\n\n---\n\n'),
    chunk_count: chunks.length
  }
}];
